"""pricing.py - Price floor and monthly price calculations."""

import pandas as pd

BASE_PRICES = {
    "Launch":          500.0,
    "Scale":           1200.0,
    "Scale Plus":      2200.0,
    "Enterprise":      4200.0,
    "Enterprise Plus": 7200.0,
}

SEAT_FLOORS = {
    "Launch":          50.0,
    "Scale":           60.0,
    "Scale Plus":      75.0,
    "Enterprise":      90.0,
    "Enterprise Plus": 110.0,
}


def calculate_price_floor(plan, seats, contract_row, migration_effective_date):
    """Calculate the applicable seat price floor for the account's plan."""
    seat_floor = SEAT_FLOORS.get(plan, 0.0)
    discount = 0.0

    # contract_row can be a series or a dictionary or a row from DataFrame
    if contract_row is not None and not (isinstance(contract_row, float) and pd.isna(contract_row)):
        # Convert series/dict if needed, get gf_until
        gf_until = None
        if hasattr(contract_row, "get"):
            gf_until = contract_row.get("grandfathered_until")
        elif isinstance(contract_row, (pd.Series, pd.DataFrame)):
            gf_until = contract_row["grandfathered_until"]

        if gf_until and not (isinstance(gf_until, float) and pd.isna(gf_until)):
            try:
                gf_dt = pd.to_datetime(gf_until)
                migration_dt = pd.to_datetime(migration_effective_date)
                if gf_dt >= migration_dt:
                    raw_pct = 0.0
                    if hasattr(contract_row, "get"):
                        raw_pct = contract_row.get("price_floor_discount_pct", 0.0)
                    else:
                        raw_pct = contract_row["price_floor_discount_pct"]

                    if pd.notna(raw_pct):
                        raw_pct = float(raw_pct)
                        if raw_pct >= 1.0:
                            discount = raw_pct / 100.0
                        else:
                            discount = raw_pct
            except Exception:
                pass

    return seat_floor * (1.0 - discount)


def calculate_expected_price(plan, seats, contract_row, migration_effective_date):
    """Calculate the expected monthly price from plan, seat count, and contract terms."""
    floor_per_seat = calculate_price_floor(plan, seats, contract_row, migration_effective_date)
    base = BASE_PRICES.get(plan, 0.0)
    return round(max(base, seats * floor_per_seat), 2)


def apply_price_exception(account_id, computed_price, approvals_df, migration_effective_date):
    """Apply price exception approvals for the account."""
    if approvals_df is None or approvals_df.empty:
        return computed_price

    acct_approvals = approvals_df[
        (approvals_df["account_id"] == account_id) &
        (approvals_df["approval_type"].str.strip().str.lower() == "price_override")
    ]

    for _, row in acct_approvals.iterrows():
        status = str(row["approval_status"]).strip().lower()
        if status != "approved":
            continue

        try:
            eff_dt = pd.to_datetime(row["effective_date"])
            exp_dt = pd.to_datetime(row["expiry_date"])
            mig_dt = pd.to_datetime(migration_effective_date)
            if eff_dt <= mig_dt <= exp_dt:
                price_val = row["approved_price"]
                if pd.notna(price_val):
                    return round(float(price_val), 2)
        except Exception:
            pass

    return computed_price
